ALTER TABLE orders ADD COLUMN customer_id BIGINT UNSIGNED NULL AFTER id, ADD KEY idx_orders_customer_id (customer_id);
CREATE TABLE IF NOT EXISTS customer_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, label VARCHAR(80) NOT NULL, full_name VARCHAR(150) NOT NULL, phone VARCHAR(40) NOT NULL, address_line1 VARCHAR(255) NOT NULL, address_line2 VARCHAR(255) NULL, city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, postal_code VARCHAR(20) NOT NULL, country VARCHAR(80) NOT NULL DEFAULT 'India', is_default TINYINT(1) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_customer_addresses_customer (customer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
